1	use std::collections::{BTreeMap, BTreeSet};
2	use std::fs;
3	use std::path::{Path, PathBuf};
4	use std::sync::Arc;
5	
6	use callisto_model::{
7	    workspace_relative, ApplyPermit, DepKind, DepLocator, DepSpec, DependencyEntry, Ecosystem, ManifestDecl,
8	    ManifestError, ManifestFormat, ManifestRole, Version, VersionGrammar, VersionReq,
9	};
10	
11	use crate::{Manifest, OpenContext};
12	
13	pub struct CargoToml {
14	    path: PathBuf,
15	    absolute: PathBuf,
16	    workspace_root: PathBuf,
17	    role: ManifestRole,
18	    document: toml_edit::DocumentMut,
19	    inherited_version: bool,
20	    inheritance: Option<Arc<WorkspaceInheritance>>,
21	    fingerprint: crate::common::FormatFingerprint,
22	}
23	
24	impl CargoToml {
25	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
26	        let rel_path = decl.path.clone();
27	        let abs_path = ctx.workspace_root.join(&rel_path);
28	
29	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
30	            path: rel_path.clone(),
31	            message: e.to_string(),
32	        })?;
33	
34	        let fingerprint = crate::common::FormatFingerprint::detect(&content);
35	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
36	
37	        let doc: toml_edit::DocumentMut =
38	            clean_content
39	                .parse()
40	                .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
41	                    path: rel_path.clone(),
42	                    format: ManifestFormat::CargoToml,
43	                    message: e.to_string(),
44	                })?;
45	
46	        let inherited_version = doc
47	            .get("package")
48	            .and_then(|p| p.get("version"))
49	            .and_then(|v| v.get("workspace"))
50	            .and_then(|w| w.as_bool())
51	            == Some(true);
52	
53	        let inherits_dependencies = dependency_locations(&doc).into_iter().any(|(section, _, target)| {
54	            dependency_table(&doc, section, target.as_deref())
55	                .is_some_and(|table| table.iter().any(|(_, item)| is_inherited_item(item)))
56	        });
57	
58	        let uses_inheritance = inherited_version || inherits_dependencies;
59	        if uses_inheritance && ctx.cargo_workspace.is_none() {
60	            return Err(ManifestError::Read {
61	                path: rel_path,
62	                message: "declares .workspace = true but no WorkspaceCargoResolver context was supplied".to_string(),
63	            });
64	        }
65	
66	        Ok(CargoToml {
67	            path: rel_path,
68	            absolute: abs_path,
69	            workspace_root: ctx.workspace_root.to_path_buf(),
70	            role: decl.role.clone(),
71	            document: doc,
72	            inherited_version,
73	            inheritance: ctx.cargo_workspace.clone(),
74	            fingerprint,
75	        })
76	    }
77	}
78	
79	/// Extracts `[package].name` from an already-parsed `Cargo.toml` document.
80	/// Pure and I/O-free -- operates on a document the caller already has,
81	/// whether that's a fully-opened [`CargoToml`] (via [`Manifest::package_name`])
82	/// or a bare parse a caller made for some other purpose entirely (e.g.
83	/// [`crate::read_identity`], which needs only a package name and deliberately
84	/// does not go through the full [`CargoToml::open`] lifecycle).
85	pub fn cargo_package_name(doc: &toml_edit::DocumentMut) -> Option<&str> {
86	    doc.get("package").and_then(|p| p.get("name")).and_then(|n| n.as_str())
87	}
88	
89	/// Rewrites a dependency entry's `version` to `new_str`, preserving decor
90	/// across the three shapes Cargo allows for a dependency value: a bare
91	/// version string, an inline table with a `version` key, or a full
92	/// `[dependencies.name]` table with a `version` key. `Err(())` for any
93	/// other shape -- callers map that to their own
94	/// `ManifestError::UnrecognizedDependencyValue` (which needs a `path` this
95	/// function has no access to). Shared by the member-manifest
96	/// ([`CargoToml::update_dependency_spec`]) and workspace-root
97	/// ([`WorkspaceCargoResolver::write_dependency`]) dependency-write paths,
98	/// which were previously two copies of this exact three-shape dance,
99	/// differing only in which path they report on error.
100	fn set_dependency_version(item: &mut toml_edit::Item, new_str: String) -> Result<(), ()> {
101	    if let Some(value) = item.as_value_mut() {
102	        if value.is_str() {
103	            let decor = value.decor().clone();
104	            let mut new_val = toml_edit::Value::from(new_str);
105	            *new_val.decor_mut() = decor;
106	            *value = new_val;
107	        } else if let Some(inline) = value.as_inline_table_mut() {
108	            if let Some(existing_ver) = inline.get_mut("version") {
109	                let decor = existing_ver.decor().clone();
110	                let mut new_val = toml_edit::Value::from(new_str);
111	                *new_val.decor_mut() = decor;
112	                *existing_ver = new_val;
113	            } else {
114	                inline.insert("version", toml_edit::Value::from(new_str));
115	            }
116	        } else {
117	            return Err(());
118	        }
119	    } else if let Some(tbl) = item.as_table_mut() {
120	        let decor = tbl.get("version").and_then(|i| i.as_value()).map(|v| v.decor().clone());
121	        tbl.insert("version", toml_edit::value(new_str));
122	        if let Some(decor) = decor {
123	            if let Some(new_item) = tbl.get_mut("version").and_then(|i| i.as_value_mut()) {
124	                *new_item.decor_mut() = decor;
125	            }
126	        }
127	    } else {
128	        return Err(());
129	    }
130	    Ok(())
131	}
132	
133	/// [`crate::read_identity`]'s `Cargo.toml` implementation: parses `source`
134	/// and extracts `[package].name` plus a [`crate::VersionSource`] for
135	/// `[package].version` -- `InheritedFromWorkspace` when it's
136	/// `version.workspace = true`, `Literal` when it's a bare string, `None`
137	/// when the field or the whole `[package]` table is absent.
138	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
139	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
140	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
141	        path: path.to_path_buf(),
142	        format: ManifestFormat::CargoToml,
143	        message: e.to_string(),
144	    })?;
145	
146	    let name = cargo_package_name(&doc).map(str::to_string);
147	    let version = doc.get("package").and_then(|p| p.get("version")).and_then(|v| {
148	        if let Some(s) = v.as_str() {
149	            Some(crate::VersionSource::Literal(s.to_string()))
150	        } else if v.get("workspace").and_then(|w| w.as_bool()) == Some(true) {
151	            Some(crate::VersionSource::InheritedFromWorkspace)
152	        } else {
153	            None
154	        }
155	    });
156	
157	    Ok(crate::ManifestIdentity { name, version })
158	}
