343	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
344	        if self.inherited_version {
345	            // The member uses `version.workspace = true` (or `version = { workspace = true }`).
346	            // Routing the bump to [workspace.package] would silently change the version for
347	            // every other workspace member. Instead, write an explicit pinned version directly
348	            // to this member's [package] section, replacing the workspace-inherited entry with
349	            // a standalone string value.
350	            let pkg = self
351	                .document
352	                .get_mut("package")
353	                .and_then(|p| p.as_table_mut())
354	                .ok_or_else(|| ManifestError::MissingField {
355	                    path: self.path.clone(),
356	                    field: "package",
357	                })?;
358	            pkg.insert("version", toml_edit::value(v.render()));
359	            self.inherited_version = false;
360	            return Ok(());
361	        }
362	
363	        let pkg = self
364	            .document
365	            .get_mut("package")
366	            .and_then(|p| p.as_table_mut())
367	            .ok_or_else(|| ManifestError::MissingField {
368	                path: self.path.clone(),
369	                field: "package",
370	            })?;
371	
372	        crate::common::set_scalar_preserving_decor(pkg, "version", v.render());
