376	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
377	        let mut entries = Vec::new();
378	
379	        for (section_name, section_kind, target) in dependency_locations(&self.document) {
380	            if let Some(table) = dependency_table(&self.document, section_name, target.as_deref()) {
381	                for (name, item) in table.iter() {
382	                    let is_inherited = is_inherited_item(item);
383	                    let mut kind = section_kind;
384	                    let local_spec = parse_cargo_dep_item(item, &mut kind);
385	                    let inherited_dep = self.inheritance.as_ref().and_then(|inh| inh.inherited(name));
386	                    let package_name = if is_inherited {
387	                        inherited_dep.map(|dep| dep.package_name).unwrap_or(name)
388	                    } else {
389	                        cargo_dependency_package_name(name, item)
390	                    };
391	
392	                    let spec = if is_inherited {
393	                        if let Some(inherited_dep) = inherited_dep {
394	                            inherited_dep.spec.clone()
395	                        } else {
396	                            DepSpec::Opaque("workspace = true (unresolved)".to_string())
397	                        }
398	                    } else {
399	                        local_spec
400	                    };
401	
402	                    entries.push(DependencyEntry {
403	                        name: name.to_string(),
404	                        package_name: package_name.to_string(),
405	                        kind,
406	                        spec,
407	                        inherited: is_inherited,
408	                        locator: DepLocator {
409	                            section: Some(section_kind),
410	                            target: target.clone(),
411	                        },
412	                    });
413	                }
414	            }
415	        }
416	
417	        Box::new(entries.into_iter())
418	    }
