420	    fn update_dependency_spec(
421	        &mut self,
422	        name: &str,
423	        kind: DepKind,
424	        at: &DepLocator,
425	        new: DepSpec,
426	        permit: &ApplyPermit,
427	    ) -> Result<(), ManifestError> {
428	        let not_found = || ManifestError::DependencyNotFound {
429	            path: self.path.clone(),
430	            name: name.to_string(),
431	            kind,
432	        };
433	        if kind == DepKind::Peer {
434	            return Err(not_found());
435	        }
436	
437	        let section = section_name(at.section.unwrap_or(kind));
438	        let item = dependency_table(&self.document, section, at.target.as_deref())
439	            .and_then(|table| table.get(name))
440	            .ok_or_else(not_found)?;
441	
442	        if is_inherited_item(item) {
443	            let root_cargo = self.workspace_root.join("Cargo.toml");
444	            if self.absolute == root_cargo {
445	                return Err(ManifestError::InvariantViolation {
446	                    path: self.path.clone(),
447	                    message: format!(
448	                        "dependency `{name}` is workspace-inherited but this manifest IS the workspace root (`{}`); refusing to delegate to avoid overwriting the just-written root manifest with a stale in-memory document",
449	                        root_cargo.display()
450	                    ),
451	                });
452	            }
453	            let mut ws_res = WorkspaceCargoResolver::load(&root_cargo)?;
454	            ws_res.write_dependency(name, new, permit)?;
455	            return ws_res.persist(permit);
456	        }
457	
458	        let item = dependency_table_mut(&mut self.document, section, at.target.as_deref())
459	            .and_then(|table| table.get_mut(name))
460	            .ok_or_else(not_found)?;
461	        set_dependency_version(item, new.render()).map_err(|()| ManifestError::UnrecognizedDependencyValue {
462	            path: self.path.clone(),
463	            name: name.to_string(),
464	        })
465	    }
