480	const DEPENDENCY_SECTIONS: [(&str, DepKind); 3] = [
481	    ("dependencies", DepKind::Runtime),
482	    ("dev-dependencies", DepKind::Dev),
483	    ("build-dependencies", DepKind::Build),
484	];
