486	/// The Cargo section a dependency kind is declared in; optional dependencies sit beside runtime ones.
487	fn section_name(kind: DepKind) -> &'static str {
488	    match kind {
489	        DepKind::Dev => "dev-dependencies",
490	        DepKind::Build => "build-dependencies",
