495	/// Every dependency table a manifest can declare: the top-level ones, then the same three
496	/// under each `[target.<cfg>]` key. Owned, so callers can mutate the document while iterating.
497	fn dependency_locations(doc: &toml_edit::DocumentMut) -> Vec<(&'static str, DepKind, Option<String>)> {
498	    let mut locations: Vec<_> = DEPENDENCY_SECTIONS
499	        .iter()
500	        .map(|(section, kind)| (*section, *kind, None))
501	        .collect();
502	    if let Some(targets) = doc.get("target").and_then(|item| item.as_table_like()) {
503	        for (cfg, _) in targets.iter() {
504	            for (section, kind) in DEPENDENCY_SECTIONS {
505	                locations.push((section, kind, Some(cfg.to_string())));
506	            }
507	        }
508	    }
509	    locations
510	}
