553	fn parse_cargo_dep_item(item: &toml_edit::Item, kind: &mut DepKind) -> DepSpec {
554	    if let Some(table) = item.as_inline_table() {
555	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
556	            *kind = DepKind::Optional;
557	        }
558	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
559	            return parse_cargo_spec_str(v_str);
560	        }
561	    } else if let Some(table) = item.as_table() {
562	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
563	            *kind = DepKind::Optional;
564	        }
565	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
566	            return parse_cargo_spec_str(v_str);
567	        }
568	    } else if let Some(v_str) = item.as_str() {
569	        return parse_cargo_spec_str(v_str);
570	    }
571	
572	    DepSpec::Opaque(item.to_string().trim().to_string())
573	}
574	
575	fn parse_cargo_spec_str(s: &str) -> DepSpec {
576	    if crate::common::is_bare_semver(s) {
577	        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
578	            return DepSpec::CargoBare(v);
579	        }
580	    }
581	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Cargo) {
582	        return DepSpec::Range(req, s.to_string());
583	    }
584	    DepSpec::Opaque(s.to_string())
585	}
586	
587	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
588	    match spec {
589	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
590	        DepSpec::Range(_, original) => {
591	            if original.contains(',') {
592	                let parts: Vec<&str> = original.split(',').collect();
593	                let mut rewritten_parts = Vec::new();
594	                for part in parts {
595	                    let part_trimmed = part.trim();
596	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
597	                    if prefix.starts_with('>')
598	                        || prefix.starts_with('=')
599	                        || prefix.starts_with('^')
600	                        || prefix.starts_with('~')
601	                    {
602	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
603	                        rewritten_parts.push(rendered);
604	                    } else if prefix.starts_with('<') {
605	                        // Upper-bound clauses are never rewritten (the clause text
606	                        // is preserved verbatim), but we must still check whether
607	                        // the target actually falls within it. If it doesn't, the
608	                        // rewrite would silently produce an impossible constraint
609	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
610	                        // does, the upper bound clause is passed through unchanged.
611	                        let bound = Version::parse(rest, target.grammar()).ok()?;
612	                        let ordering = target.partial_compare(&bound)?;
613	                        let exceeds_bound = if prefix == "<=" {
614	                            ordering == std::cmp::Ordering::Greater
615	                        } else {
616	                            ordering != std::cmp::Ordering::Less
617	                        };
618	                        if exceeds_bound {
619	                            return None;
620	                        }
621	                        rewritten_parts.push(part_trimmed.to_string());
622	                    } else {
623	                        rewritten_parts.push(part_trimmed.to_string());
624	                    }
625	                }
626	                let rendered = rewritten_parts.join(", ");
627	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
628	                return Some(DepSpec::Range(req, rendered));
629	            }
630	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
631	            if rest.contains('*') {
632	                return None;
633	            }
634	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
635	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
636	            Some(DepSpec::Range(req, rendered))
637	        }
638	        _ => None,
639	    }
640	}
641	
642	fn render_at_precision(target: &Version, original_clause: &str) -> String {
643	    if original_clause.contains('-') || target.is_prerelease() {
644	        return target.render().to_string();
645	    }
646	    let parts: Vec<&str> = original_clause.split('.').collect();
647	    let maj = target.major().unwrap_or(0);
648	    let min = target.minor().unwrap_or(0);
649	    let pat = target.patch().unwrap_or(0);
650	
651	    match parts.len() {
652	        1 => format!("{maj}"),
653	        2 => format!("{maj}.{min}"),
654	        _ => format!("{maj}.{min}.{pat}"),
655	    }
656	}
