690	    pub fn load(root_manifest_path: &Path) -> Result<Self, ManifestError> {
691	        crate::record_resolver_load_call();
692	        let rel_path = if root_manifest_path.is_absolute() {
693	            root_manifest_path
694	                .file_name()
695	                .map(PathBuf::from)
696	                .unwrap_or_else(|| PathBuf::from("Cargo.toml"))
697	        } else {
698	            workspace_relative(root_manifest_path).map_err(|e| ManifestError::Read {
699	                path: root_manifest_path.to_path_buf(),
700	                message: e.to_string(),
701	            })?
702	        };
703	        let content = fs::read_to_string(root_manifest_path).map_err(|e| ManifestError::Read {
704	            path: rel_path.clone(),
705	            message: e.to_string(),
706	        })?;
707	
708	        let doc: toml_edit::DocumentMut = content
709	            .parse()
710	            .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
711	                path: rel_path.clone(),
712	                format: ManifestFormat::CargoToml,
713	                message: e.to_string(),
714	            })?;
715	
716	        Ok(WorkspaceCargoResolver {
717	            root_path: rel_path,
718	            absolute_path: root_manifest_path.to_path_buf(),
719	            document: doc,
720	        })
721	    }
