270	                            rewrite_attempted.insert(key.clone());
271	                            out.rewrites.insert(
272	                                key.clone(),
273	                                SpecRewrite {
274	                                    key,
275	                                    dependency: edge.to.clone(),
276	                                    from: edge.spec.clone(),
277	                                    to: to_spec,
278	                                },
279	                            );
280	                        }
281	                        RewriteOutcome::LeftAlone(dg) => {
282	                            rewrite_attempted.insert(dependency_rewrite_key(&edge));
283	                            out.diagnostics.push(dg);
284	                        }
285	                    }
286	                }
287	
288	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
289	                if d.severity > cur_sev {
290	                    raise(
291	                        &edge.from,
292	                        d.severity,
293	                        &d,
294	                        &pkg,
295	                        &edge,
296	                        &new_version,
297	                        &mut out,
298	                        input.groups,
299	                        &mut worklist,
300	                        &input,
301	                    )?;
302	                }
303	            }
304	        }
305	
306	        // Linked group release severity propagation
307	        for g in input.groups.linked.values() {
308	            let max_sev = g.max_severity(&out.severities);
309	            if max_sev == Severity::None {
310	                continue;
311	            }
312	
313	            // A member absent from `input.base` was removed from the
314	            // workspace but is still listed in the group config. Skip it
315	            // rather than let `bump_target` below hit `MissingField` --
316	            // mirrors the guard `aggregate::union_fixed`/`union_linked`
317	            // already apply before cascade convergence ever starts.
318	            let mut live_members = Vec::new();
319	            for id in g.package_members() {
320	                if !input.base.contains_key(id) {
321	                    out.diagnostics.push(Diagnostic {
322	                        code: DiagnosticCode::UnknownPackage,
323	                        severity: DiagnosticSeverity::Warning,
324	                        message: format!(
325	                            "Linked group `{}` references package `{}` which is not in the \
326	                             workspace; the stale group member is skipped. Remove it from \
327	                             callisto.toml to silence this warning.",
328	                            g.name,
329	                            id.display_name()
330	                        ),
331	                        package: Some(id.clone()),
332	                        path: None,
333	                        governed_by: Some(ConfigKey::LINKED_GROUP),
334	                        escalated_by: None,
335	                    });
336	                    continue;
337	                }
338	                live_members.push(id.clone());
339	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
340	                if max_sev > cur_sev {
341	                    out.severities.insert(id.clone(), max_sev);
342	                }
343	            }
344	
345	            let mut winner: Option<Version> = None;
346	            for id in &live_members {
347	                let candidate = bump_target(id, max_sev, &input)?;
348	                winner = Some(match winner {
349	                    None => candidate,
350	                    Some(best) => {
351	                        let cmp = Version::compare(&candidate, &best).map_err(|_grammar_mismatch| {
352	                            GraphError::GroupGrammarMismatch {
353	                                group: g.name.clone(),
354	                                members: live_members
355	                                    .iter()
356	                                    .filter_map(|m| out.targets.get(m).map(|v| (m.clone(), v.clone())))
357	                                    .collect(),
358	                            }
359	                        })?;
360	                        if cmp.is_gt() {
361	                            candidate
362	                        } else {
363	                            best
364	                        }
365	                    }
366	                });
367	            }
368	            let Some(winner) = winner else { continue };
369	
370	            for id in live_members {
371	                if out.targets.get(&id) != Some(&winner) {
372	                    out.targets.insert(id.clone(), winner.clone());
373	                    out.reasons
374	                        .insert(id.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
375	                    worklist.insert(id.clone());
376	                    changed = true;
377	                }
378	            }
379	        }
380	
381	        // Fixed group convergence -- mirrors the Linked-group block
382	        // above but computes each group's shared target via
383	        // fixed_group_target instead of taking the max of independently
384	        // bumped per-member candidates.
385	        for g in input.groups.fixed.values() {
386	            let max_sev = g.max_severity(&out.severities);
387	            if max_sev == Severity::None {
388	                continue;
389	            }
390	
391	            // A member absent from `input.base` was removed from the
392	            // workspace but is still listed in the group config. Skip it
393	            // rather than let it flow into `out.severities`/`out.targets`,
394	            // which `plan_version`'s `pkg_map.get(id).copied().unwrap()`
395	            // (built only from live graph packages) would later panic on --
396	            // mirrors the guard `aggregate::union_fixed`/`union_linked` and
397	            // the Linked-group block above already apply.
398	            let mut live_members = Vec::new();
399	            for id in g.package_members() {
400	                if !input.base.contains_key(id) {
401	                    out.diagnostics.push(Diagnostic {
402	                        code: DiagnosticCode::UnknownPackage,
403	                        severity: DiagnosticSeverity::Warning,
404	                        message: format!(
405	                            "Fixed group `{}` references package `{}` which is not in the \
406	                             workspace; the stale group member is skipped. Remove it from \
407	                             callisto.toml to silence this warning.",
408	                            g.name,
409	                            id.display_name()
410	                        ),
411	                        package: Some(id.clone()),
412	                        path: None,
413	                        governed_by: Some(ConfigKey::FIXED_GROUP),
414	                        escalated_by: None,
415	                    });
416	                    continue;
417	                }
418	                live_members.push(id.clone());
419	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
420	                if max_sev > cur_sev {
421	                    out.severities.insert(id.clone(), max_sev);
422	                }
423	            }
424	
425	            let winner =
426	                crate::groups::fixed_group_target(&g.name, &live_members, input.base, max_sev, input.tags, input.pre)?;
427	
428	            for id in live_members {
429	                if out.targets.get(&id) != Some(&winner) {
430	                    out.targets.insert(id.clone(), winner.clone());
431	                    out.reasons
432	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
433	                    worklist.insert(id.clone());
434	                    changed = true;
435	                }
436	            }
437	        }
438	    }
439	
440	    // A releasing package's floor on a co-released dependency is always raised, even when the old spec still covers it.
441	    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
442	        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
443	        for edge in deps {
444	            if edge.kind == DepKind::Dev {
445	                continue;
446	            }
447	            if matches!(
448	                edge.spec,
449	                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
450	            ) {
451	                continue;
452	            }
453	            let Some(new_version) = out.targets.get(&edge.to).cloned() else {
454	                continue;
455	            };
456	            if matches!(edge.spec, DepSpec::WorkspaceProtocol(_))
457	                && coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
458	                    from: edge.from.clone(),
459	                    to: edge.to.clone(),
460	                    source,
461	                })? != Coverage::DoesNotCover
462	            {
463	                continue;
464	            }
465	
466	            let eco = manifest_ecosystem(&edge.from_manifest);
467	
468	            let key = dependency_rewrite_key(&edge);
469	            if rewrite_attempted.contains(&key) {
470	                continue;
471	            }
472	
473	            match rewrite_spec(&edge.spec, &new_version, eco, input.cfg) {
474	                RewriteOutcome::Rewritten(to_spec) => {
475	                    out.rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
476	                        key,
477	                        dependency: edge.to.clone(),
478	                        from: edge.spec.clone(),
479	                        to: to_spec,
480	                    });
481	                }
482	                RewriteOutcome::LeftAlone(dg) => {
483	                    out.diagnostics.push(dg);
484	                }
485	            }
486	        }
487	    }
488	
489	    out.iterations = iterations;
490	    Ok(out)
491	}
492	
493	fn bump_target<D: DependencyResolver>(
494	    id: &PackageId,
495	    sev: Severity,
496	    input: &CascadeInput<'_, D>,
497	) -> Result<Version, GraphError> {
498	    let base = input.base.get(id).cloned().ok_or_else(|| {
499	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
500	            path: PathBuf::from(id.name()),
501	            field: "version",
502	        })
503	    })?;
504	
505	    // PreMode::Exit falls through to a plain `versioning.bump`, which strips a matching pre-release tag directly.
506	    crate::groups::versioned_bump(id, &base, sev, input.pre)
507	}
508	
509	#[allow(clippy::too_many_arguments)]
510	fn raise<D: DependencyResolver>(
511	    pkg: &PackageId,
512	    sev: Severity,
513	    decision: &CascadeDecision,
514	    via: &PackageId,
515	    edge: &DepEdge,
516	    dependency_to: &Version,
517	    out: &mut CascadeOutcome,
518	    groups: &GroupTable,
519	    worklist: &mut BTreeSet<PackageId>,
520	    input: &CascadeInput<'_, D>,
521	) -> Result<bool, GraphError> {
522	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
523	    if sev <= cur_sev {
524	        return Ok(false);
525	    }
526	
527	    out.severities.insert(pkg.clone(), sev);
528	
529	    let new_reason = if decision.escalated {
530	        BumpReason::PeerEscalation {
531	            via: via.clone(),
532	            spec: edge.spec.render(),
533	        }
534	    } else {
535	        BumpReason::Cascade {
536	            via: via.clone(),
537	            dep_kind: edge.kind,
538	            spec: edge.spec.render(),
539	            dependency_to: dependency_to.clone(),
540	        }
541	    };
542	    out.reasons.insert(pkg.clone(), new_reason);
543	
544	    if let Some(ref gov) = decision.governed_by {
545	        out.governed_by.insert(pkg.clone(), gov.clone());
546	    }
547	
548	    let new_t = bump_target(pkg, sev, input)?;
549	    out.targets.insert(pkg.clone(), new_t);
550	    worklist.insert(pkg.clone());
551	
552	    for sib in groups.fixed_siblings(pkg) {
553	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
554	        if sev > sib_sev {
555	            out.severities.insert(sib.clone(), sev);
556	            out.reasons.insert(
557	                sib.clone(),
558	                BumpReason::FixedGroupUnion {
559	                    group: groups.fixed_group_of(pkg).unwrap().name.clone(),
560	                },
561	            );
562	            let sib_t = bump_target(sib, sev, input)?;
563	            out.targets.insert(sib.clone(), sib_t);
564	            worklist.insert(sib.clone());
565	        }
566	    }
567	
568	    Ok(true)
569	}
570	
571	pub(crate) fn convergence_bound(package_count: usize) -> usize {
572	    4 * package_count + 1
573	}
574	
575	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
576	pub enum DepWriteTarget {
577	    Manifest(PathBuf),
578	    CargoWorkspaceDependency { root_manifest: PathBuf },
579	}
580	
581	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
582	pub struct RewriteKey {
583	    pub target: DepWriteTarget,
584	    pub name: String,
585	    pub kind: Option<DepKind>,
586	    pub locator: DepLocator,
587	}
588	
589	#[derive(Clone, Debug, PartialEq, Eq)]
590	pub struct SpecRewrite {
591	    pub key: RewriteKey,
592	    pub dependency: PackageId,
593	    pub from: DepSpec,
594	    pub to: DepSpec,
595	}
596	
597	pub enum RewriteOutcome {
598	    Rewritten(DepSpec),
599	    LeftAlone(Diagnostic),
600	}
601	
602	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
603	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
604	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
605	    }
606	
607	    if let Some(rewritten) = callisto_manifests::round_trip(eco, original, new) {
608	        RewriteOutcome::Rewritten(rewritten)
609	    } else {
610	        RewriteOutcome::LeftAlone(Diagnostic {
611	            code: DiagnosticCode::RangeNotRoundTrippable,
612	            severity: DiagnosticSeverity::Warning,
613	            message: format!(
614	                "spec `{}` could not be round-tripped toward version `{}`",
615	                original.render(),
616	                new.render()
617	            ),
618	            package: None,
619	            path: None,
620	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
621	            escalated_by: None,
622	        })
623	    }
624	}
