204	        node_map.insert(pkg.clone(), idx);
205	        rev_map.insert(idx, pkg.clone());
206	    }
207	
208	    for u in remaining {
209	        if let Some(neighbors) = adj.get(u) {
210	            for v in neighbors {
211	                if let (Some(&u_idx), Some(&v_idx)) = (node_map.get(u), node_map.get(v)) {
212	                    graph.add_edge(u_idx, v_idx, ());
