238	                    curr = next;
239	                    cycle.push(rev_map[&curr].clone());
240	                    if curr == start_idx {
241	                        break;
242	                    }
243	                } else {
244	                    break;
245	                }
246	            }
247	
248	            if cycle.len() > 1 {
249	                return cycle;
250	            }
251	        }
252	    }
